  }
  const aN=aS/6.7, iN=iS/6.7, wN=wS/4.2;
  const bg1 = (Math.sin(sx*0.035+sy*0.022+t*0.75)+Math.sin(sx*0.028-sy*0.038+t*1.05))/2;
  const bg2 = (Math.sin((sx+sy)*0.1+t*2.2)*0.3+Math.sin((sx-sy)*0.09-t*1.8)*0.3);
  const bg3 = Math.sin(sx*0.06+t*1.5)*Math.sin(sy*0.055-t*1.3)*0.4;
